Aim: Implement a servlet for checking user login if the user name and 
password is right then it will move to the welcome servlet. 
Code:- 
index.html— 
<!DOCTYPE html> 
<html>  
<head>  
<title>Login Form</title>  
</head> 
<body> <form action="LoginServlet" > 
Enter User ID<input type="text" name="txtId"><br> 
Enter Password<input type="password" name="txtPass"><br> 
<input type="reset"> 
<input type="submit" value=" Click to Login " > 
</form>  
</body> </html> 


LoginServlet--- 
package mypack; 
import java.io.*; 
import javax.servlet.ServletException; 
import javax.servlet.annotation.WebServlet; 
import javax.servlet.http.*; 
@WebServlet(urlPatterns = {"/LoginServlet"}) 
public class LoginServlet extends HttpServlet { 
protected void doGet(HttpServletRequest request, HttpServletResponse response) throws 
ServletException, IOException { 
response.setContentType("text/html;charset=UTF-8"); 

PrintWriter out = response.getWriter(); 
String uname = request.getParameter("txtId"); 
String upass = request.getParameter("txtPass"); 
          out.println("<html><head><title>Servlet LoginServlet</title></head>"); 
if (uname != null && upass != null && uname.equals("admin") && upass.equals("12345")) { 
out.println("<body bgcolor='green'>"); 
out.println("<h1> Welcome !!! " + uname + "</h1>"); 
} else { 
out.println("<body bgcolor='grey'>"); 
out.println("<h1> Login Fail !!! </h1>"); 
} 
out.println("</body></html>"); 
} 
}

