Code:- 
INDEX.html--- 
<!DOCTYPE html> <html lang="en"> <head>  
    <meta charset="UTF-8">  
    <meta name="viewport" content="width=device-width, initial-scale=1.0">  
    <title>Login Form</title> </head>  
<body>  
    <h2>Login</h2>  
    <form action="login_servlet" method="GET">  
        Enter User ID: <input type="text" name="txtId" required><br>  
        Enter Password: <input type="password" name="txtPass" required><br><br>  
        <input type="reset" value="Reset">  
        <input type="submit" value="Click to Login">  
    </form>  
</body> 
</html> 

login_servlet.java 
import java.io.IOException; 
import java.io.PrintWriter; 
import javax.servlet.RequestDispatcher; 
import javax.servlet.ServletException; 
import javax.servlet.annotation.WebServlet; 
import javax.servlet.http.HttpServlet; 
import javax.servlet.http.HttpServletRequest; 
import javax.servlet.http.HttpServletResponse; 

/** 
 * 
 * @author aditi 
 */ 
@WebServlet(urlPatterns = {"/login_servlet"}) 
public class login_servlet extends HttpServlet { 

       public void doGet(HttpServletRequest request, HttpServletResponse response)  
            throws ServletException, IOException {  
        // Set the content type to HTML  
        response.setContentType("text/html;charset=UTF-8");  
        PrintWriter out = response.getWriter();  
        out.println("<html><head>");  
        out.println("<title>Servlet LoginServlet</title></head>");  
        String uname = request.getParameter("txtId");  
        String upass = request.getParameter("txtPass");  
        // Check for null values before calling .equals() to prevent NullPointerException  
        if (uname != null && upass != null && uname.equals("admin") && upass.equals("servlet")) {  // 
Forward to WelcomeServlet on successful login  
            RequestDispatcher rd = request.getRequestDispatcher("welcomeservlet");  
            rd.forward(request, response);  } else {  
            // Show error message if login fails  
            out.println("<body bgcolor='red'>");  
            out.println("<h1>Login Failed!!!</h1>");  
            out.println("<p>Invalid User ID or Password.</p>");  
            // Include the login form again  
            RequestDispatcher rd = request.getRequestDispatcher("index.html");  
            rd.include(request, response);  }  
        out.println("</body>"); out.println("</html>"); 
 } 

 }
welcomeservlet.java 
import java.io.IOException; 
import java.io.PrintWriter; 
import javax.servlet.ServletException; 
import javax.servlet.annotation.WebServlet; 
import javax.servlet.http.HttpServlet; 
import javax.servlet.http.HttpServletRequest; 
import javax.servlet.http.HttpServletResponse; 

/** 
 * 
 * @author aditi 
 */ 
@WebServlet(urlPatterns = {"/welcomeservlet"}) 
public class welcomeservlet extends HttpServlet { 

    @Override 
    protected void doGet(HttpServletRequest request, HttpServletResponse response)  
            throws ServletException, IOException {     
        // Setting content type and obtaining PrintWriter to write response  
        response.setContentType("text/html;charset=UTF-8");  
        PrintWriter out = response.getWriter();  
        // Displaying welcome message upon successful login  
        out.println("<html><head>");  
        out.println("<title>Welcome Servlet</title></head>");  
        out.println("<body>");  
        out.println("<h1>Welcome, admin!</h1>");   
        out.println("<p>Login was successful!</p>");  
        out.println("</body></html>");  
    }  
} 
